    for i in range(8):
        used.append([0] * 8)
    v = []
    for i in range(8):
        s = data[idx]
        idx += 1
        ar.append(s)
        for j in range(8):
            if s[j] == 'S':
                v.append((i, j))

    x = dfs(7, 0, list(v), [row[:] for row in used])
    if x == 1:
        print("WIN")
        return
